// The three packs that ship first (#244): colors (8), counting (1-10, then 11-20, numeral matched to
// quantity both ways) and shapes (6). Every item, choice set and answer key below is data; the few
// generated with a loop are generated by plain arithmetic, not a model. packs.test.ts checks that
// every pack is internally valid (each key is among its choices, ids are unique and stable, choice
// colors differ in lightness).

import type { Choice, ColorId, Item, Pack, PackId, ShapeId, Skill, SkillId } from "./types";

/** The key an answer is stored as: "n:4", "dots:7", "color:red", "shape:star". */
export function choiceKey(c: Choice): string {
  switch (c.kind) {
    case "numeral": return `n:${c.n}`;
    case "dots": return `dots:${c.n}`;
    case "color": return `color:${c.color}`;
    case "shape": return `shape:${c.shape}`;
  }
}

/** Child-facing word for a choice: aria-labels and what the voice says. */
export function choiceLabel(c: Choice): string {
  switch (c.kind) {
    case "numeral": return String(c.n);
    case "dots": return `${c.n} ${c.n === 1 ? "dot" : "dots"}`;
    case "color": return c.color;
    case "shape": return c.shape;
  }
}

// ── Colors ──────────────────────────────────────────────────────────────────────────────────────────
// Fill colors for the swatches. Picked so the three in any one item also differ in lightness, not only
// hue (WCAG relative luminance, contrast >= 1.5 between every pair; packs.test.ts enforces it), so a
// child with red-green color blindness still sees three different swatches. Red and green are never
// offered together. These are picture content, so they are the same in light and dark mode.
export const COLOR_HEX: Record<ColorId, string> = {
  red: "#D7263D",
  orange: "#F28C28",
  yellow: "#FFD84D",
  green: "#2E8540",
  blue: "#2563EB",
  purple: "#6B2FA6",
  pink: "#F7A1C4",
  brown: "#7A4A24",
};

export const COLORS: ReadonlyArray<ColorId> = ["red", "orange", "yellow", "green", "blue", "purple", "pink", "brown"];

// Each color with the two it is shown beside.
const COLOR_DISTRACTORS: Record<ColorId, [ColorId, ColorId]> = {
  red: ["yellow", "purple"],
  orange: ["purple", "yellow"],
  yellow: ["green", "orange"],
  green: ["pink", "purple"],
  blue: ["yellow", "purple"],
  purple: ["green", "pink"],
  pink: ["red", "purple"],
  brown: ["orange", "green"],
};

const colorItems: Item[] = COLORS.map((color) => ({
  id: `colors/${color}`,
  skillId: "colors",
  prompt: `Find ${color}.`,
  picture: { kind: "none" },
  choices: [color, ...COLOR_DISTRACTORS[color]].map((c) => ({ kind: "color", color: c })),
  answer: `color:${color}`,
  praise: `Yes! That is ${color}.`,
  teach: { say: `This is ${color}. Find the one that looks like it.`, countAlong: false, example: { kind: "color", color } },
}));

// ── Counting ────────────────────────────────────────────────────────────────────────────────────────

/** Three numbers next to n inside [lo, hi]: n-1, n, n+1, slid inward at the ends. */
export function neighbours(n: number, lo: number, hi: number): number[] {
  const start = Math.min(Math.max(n - 1, lo), hi - 2);
  return [start, start + 1, start + 2];
}

function countList(n: number): string {
  return Array.from({ length: n }, (_, i) => i + 1).join(", ");
}

function countingItems(skillId: SkillId, lo: number, hi: number): Item[] {
  const items: Item[] = [];
  for (let n = lo; n <= hi; n++) {
    const apples = n === 1 ? "apple" : "apples";
    // Quantity -> numeral: count the apples, tap the number.
    items.push({
      id: `${skillId}/how-many-${n}`,
      skillId,
      prompt: "How many apples?",
      picture: { kind: "apples", count: n },
      choices: neighbours(n, lo === 1 ? 1 : lo - 1, hi).map((k) => ({ kind: "numeral", n: k })),
      answer: `n:${n}`,
      praise: `Yes! ${n} ${apples}.`,
      teach: { say: `Let's count them together: ${countList(n)}.`, countAlong: true, example: null },
    });
    // Numeral -> quantity: read the number, tap the group with that many.
    items.push({
      id: `${skillId}/find-${n}`,
      skillId,
      prompt: `Find ${n} ${n === 1 ? "dot" : "dots"}.`,
      picture: { kind: "numeral", n },
      choices: neighbours(n, lo === 1 ? 1 : lo - 1, hi).map((k) => ({ kind: "dots", n: k })),
      answer: `dots:${n}`,
      praise: `Yes! That is ${n}.`,
      teach: { say: `This is ${n}. Let's count ${n} together: ${countList(n)}.`, countAlong: true, example: { kind: "apples", count: n } },
    });
  }
  return items;
}

// ── Shapes ──────────────────────────────────────────────────────────────────────────────────────────

export const SHAPES: ReadonlyArray<ShapeId> = ["circle", "square", "triangle", "rectangle", "star", "heart"];

const SHAPE_DISTRACTORS: Record<ShapeId, [ShapeId, ShapeId]> = {
  circle: ["square", "triangle"],
  square: ["rectangle", "circle"],
  triangle: ["circle", "star"],
  rectangle: ["square", "heart"],
  star: ["triangle", "heart"],
  heart: ["circle", "star"],
};

const SHAPE_HINT: Record<ShapeId, string> = {
  circle: "It is round.",
  square: "It has 4 sides, all the same.",
  triangle: "It has 3 sides.",
  rectangle: "It has 4 sides: 2 long and 2 short.",
  star: "It has 5 points.",
  heart: "It has two bumps on top and a point at the bottom.",
};

const shapeItems: Item[] = SHAPES.map((shape) => ({
  id: `shapes/${shape}`,
  skillId: "shapes",
  prompt: `Find the ${shape}.`,
  picture: { kind: "none" },
  choices: [shape, ...SHAPE_DISTRACTORS[shape]].map((s) => ({ kind: "shape", shape: s })),
  answer: `shape:${shape}`,
  praise: `Yes! That is a ${shape}.`,
  teach: { say: `This is a ${shape}. ${SHAPE_HINT[shape]}`, countAlong: false, example: { kind: "shape", shape } },
}));

