export const PACKS: ReadonlyArray<Pack> = [
  { id: "colors", title: "Colors", skills: ["colors"] },
  { id: "counting", title: "Counting", skills: ["count-1-10", "count-11-20"] },
  { id: "shapes", title: "Shapes", skills: ["shapes"] },
];

export function packOf(id: PackId): Pack {
  return PACKS.find((p) => p.id === id)!;
}

/** Every item in every skill, by id. */
export const ITEMS_BY_ID: ReadonlyMap<string, Item> = new Map(
  Object.values(SKILLS).flatMap((s) => s.items).map((i) => [i.id, i]),
);
